from scipy.optimize import least_squares
y=dP_dt; yv=np.var(y)
fams={
 'tPexp': lambda g,k,m: t**k*P**m*np.exp(-g*t),
 'tP_sat': lambda g,k,m: t**k*P**m/(1+g*P),
 'tP_logistic': lambda g,k,m: t**k*P*(1-P/g),
 'expP_t': lambda g,k,m: t**k*np.exp(-g*P),
 'P_t_tanh': lambda g,k,m: t**k*P**m*np.tanh(g*t),
}
for name,F in fams.items():
    def mdl(q):
        a,b,c_,d,e,f,g,k,m=q
        return a*np.tanh(b*t)+c_*np.tanh(d*t)*P**3+e*F(g,k,m)+f*P**2
    def rf(q): return (y-mdl(q))/np.sqrt(yv)
    best=None; rng=np.random.default_rng(1)
    for s in range(150):
        q0=np.array([rng.normal()*5,rng.uniform(0.05,1),rng.normal(),rng.uniform(0.05,1),rng.normal(),rng.normal(),rng.uniform(0.1,2),rng.uniform(0,2),rng.uniform(0,2)])
        try: r=least_squares(rf,q0,max_nfev=300)
        except Exception: continue
        if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
    print(name, np.mean(best.fun**2), np.round(best.x,4))
